// Generated by OrchestKit Claude Plugin
// Created: 2026-07-31

// Server-side analytics chokepoint. The browser's counterpart is
// lib/search-beacon.ts; this is the same contract for code that runs on the
// server (middleware + Node route handlers), where `navigator.sendBeacon` and
// posthog-js do not exist.
//
// WHY NOT JUST POST TO /api/analytics FROM THE SERVER
// app/api/analytics is an edge handler that derives `visitor_id` by HMAC-ing the
// INBOUND request's client IP, then stamps country + user-agent from that same
// request. A same-origin hop from a route handler makes the inbound IP a
// Vercel-internal one, so every server-emitted event would collapse onto a
// single visitor_id with the wrong country and a server user-agent. This module
// therefore does what the edge handler does — byte-for-byte the same envelope
// and the same HMAC signature — but reads the ORIGINAL request's headers and
// posts straight to HQ. One hop, correct visitor_id, no second envelope format.
//
// WHY THERE IS NO POSTHOG MIRROR HERE
// posthog-js is a browser SDK and cannot run in middleware or a route handler,
// and posthog-node cannot run in the Edge runtime at all — which is exactly
// where the discovery surface (/.well-known/*, /openapi.json, /llms.txt) is
// observable, since those handlers are prerendered and never execute per
// request. Adding posthog-node would buy nothing on the surface that needs it
// most, would create a SECOND event-name emission path (the drift the
// single-chokepoint rule exists to prevent), and would require a per-event
// `$process_person_profile: false` invariant on anonymous crawler traffic —
// one missed call site mints a billable person row per distinct client.
// So: server events are first-party only, by design. The first-party sink is
// the system of record; if PostHog ever needs this data it gets backfilled from
// HQ server-to-server, off the request path.
//
// Fail-open everywhere: telemetry must never fail, delay, or alter a response.

import { after } from "next/server";

const PROJECT_ID = "orchestkit";
const INGEST_TIMEOUT_MS = 3000;

// Caps enforced by the authoritative sink's Pydantic schema. Exceeding one
// rejects the WHOLE batch with a 500, silently, since nothing here reads the
// response — so they are clamped locally rather than trusted.
const MAX_EVENT_NAME = 50;
const MAX_PATH = 500;
const MAX_USER_AGENT = 500;
const MAX_EVENTS = 100;

export type ServerEventProps = Record<string, string | number | boolean>;

export type ServerEvent = {
	/** `<namespace>:<kebab-leaf>`, matching the shipped client convention. */
	name: string;
	/** Request path. Top-level envelope field — do NOT duplicate in properties. */
	path: string;
	properties: ServerEventProps;
};

let cachedKey: CryptoKey | null = null;
let cachedSecret: string | null = null;

async function hmacKey(secret: string): Promise<CryptoKey> {
	if (cachedKey && cachedSecret === secret) return cachedKey;
	cachedKey = await crypto.subtle.importKey(
		"raw",
		new TextEncoder().encode(secret),
		{ name: "HMAC", hash: "SHA-256" },
		false,
		["sign"],
	);
	cachedSecret = secret;
	return cachedKey;
}

function toHex(buf: ArrayBuffer): string {
	return Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, "0")).join(
		"",
	);
}

function clientIp(headers: Headers): string {
	return (
		headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
		headers.get("x-real-ip") ||
		"unknown"
	);
}

/**
 * Build, sign, and POST one batch to the HQ ingest endpoint.
 *
 * Exported (rather than only the fire-and-forget wrapper) so tests can await a
 * deterministic send. Production callers should use `reportServerEvents`.
 *
 * No-ops when unconfigured, so local dev and CI never emit.
 */
export async function deliverServerEvents(
	headers: Headers,
	events: readonly ServerEvent[],
): Promise<void> {
	const hqApiUrl = process.env.HQ_API_URL;
	const secret = process.env.ANALYTICS_HMAC_SECRET;
	if (!hqApiUrl || !secret) return;

	// An over-long name is batch-fatal at the sink and unobservable here, so it
	// is dropped rather than sent.
	const safe = events
		.filter((e) => e.name.length > 0 && e.name.length <= MAX_EVENT_NAME)
		.slice(0, MAX_EVENTS);
	if (safe.length === 0) return;

	try {
		const encoder = new TextEncoder();
		const key = await hmacKey(secret);
		const visitorId = toHex(
			await crypto.subtle.sign("HMAC", key, encoder.encode(clientIp(headers))),
		);
		// Key order matches the edge handler's `{...body, visitor_id, country,
		// user_agent}` spread. The signature is over these exact bytes.
		const body = JSON.stringify({
			project_id: PROJECT_ID,
			events: safe.map((e) => ({
				name: e.name,
				path: e.path.slice(0, MAX_PATH),
				referrer: "",
				properties: e.properties,
			})),
			visitor_id: visitorId,
			country: headers.get("x-vercel-ip-country") || null,
			user_agent: headers.get("user-agent")?.slice(0, MAX_USER_AGENT) || null,
		});
		const sig = toHex(await crypto.subtle.sign("HMAC", key, encoder.encode(body)));
		await fetch(`${hqApiUrl}/api/analytics/ingest`, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				"X-Analytics-Signature": `sha256=${sig}`,
			},
			body,
			signal: AbortSignal.timeout(INGEST_TIMEOUT_MS),
		});
	} catch {
		// fail-open: a dead sink, a timeout, or a missing Web Crypto must never
		// surface to the request.
	}
}

/**
 * Fire-and-forget a batch of server events.
 *
 * The work is handed to Next's `after()`, which runs it once the response has
 * been sent while keeping the serverless invocation alive — so nothing is lost
 * to a freeze and nothing is added to the hot path's latency. This is the whole
 * reason no batching SDK (and no awaited flush) is needed.
 */
export function reportServerEvents(
	headers: Headers,
	events: readonly ServerEvent[],
): void {
	if (events.length === 0) return;
	try {
		after(() => deliverServerEvents(headers, events));
	} catch {
		// `after()` throws outside a request scope (tests, scripts). Telemetry is
		// not worth a crash; drop it.
	}
}

/** Single-event convenience wrapper over {@link reportServerEvents}. */
export function reportServerEvent(
	headers: Headers,
	name: string,
	path: string,
	properties: ServerEventProps,
): void {
	reportServerEvents(headers, [{ name, path, properties }]);
}
